import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double x = scanner.nextDouble();
        double y = scanner.nextDouble();
        int n = scanner.nextInt();

        double minDiff = 2e9;
        double bestA = 0;
        double bestB = 1;
        double ratio = x / y;

        for (int i = 1; i <= n; i++) {
            long a = (long) (ratio * i);
            double diff1 = Math.abs((double) a / i - ratio);
            double diff2 = Math.abs((double) (a + 1) / i - ratio);

            if (diff1 <= diff2 && diff1 < minDiff) {
                minDiff = diff1;
                bestA = a;
                bestB = i;
            } else if (diff2 < minDiff) {
                minDiff = diff2;
                bestA = a + 1;
                bestB = i;
            }
        }
        System.out.println((long) bestA + "/" + (long) bestB);
        scanner.close();
    }
}
